  pay(day: Day, pence: Pence, method: PayMethod = "transfer", ref: string = ""): Pence {
    const wanted = ref.toLowerCase();
    const duplicate =
      ref !== "" && this.payments.some((p) => p.ref !== "" && p.ref.toLowerCase() === wanted);
    if (!duplicate) return this.recordPayment(day, pence, method, ref);
    // Run the original checks so anything that threw before still throws,
